CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE evaluation_program(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,name text NOT NULL,scope jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',owner_id uuid NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,name));
CREATE TABLE evaluation_dataset(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,program_id uuid NOT NULL,name text NOT NULL,version integer NOT NULL,source_ref text NOT NULL,checksum text NOT NULL,status text NOT NULL DEFAULT 'pending',validated_by uuid,validated_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,program_id,name,version),FOREIGN KEY(program_id,tenant_id) REFERENCES evaluation_program(id,tenant_id));
CREATE TABLE evaluation_scenario(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,program_id uuid NOT NULL,name text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'draft',approved_by uuid,approved_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(program_id,tenant_id) REFERENCES evaluation_program(id,tenant_id));
CREATE TABLE evaluation_test_case(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scenario_id uuid NOT NULL,dataset_id uuid NOT NULL,input jsonb NOT NULL,expected_properties jsonb NOT NULL,prohibited_properties jsonb NOT NULL DEFAULT '[]',criteria jsonb NOT NULL,severity text NOT NULL,status text NOT NULL DEFAULT 'draft',approved_by uuid,approved_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(scenario_id,tenant_id) REFERENCES evaluation_scenario(id,tenant_id),FOREIGN KEY(dataset_id,tenant_id) REFERENCES evaluation_dataset(id,tenant_id));
CREATE TABLE evaluation_subject(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,subject_type text NOT NULL,subject_id text NOT NULL,subject_version text NOT NULL,configuration jsonb NOT NULL,lineage jsonb NOT NULL,registered_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,subject_type,subject_id,subject_version));
CREATE TABLE evaluation_run(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,program_id uuid NOT NULL,subject_id uuid NOT NULL,dataset_id uuid NOT NULL,status text NOT NULL DEFAULT 'scheduled',started_at timestamptz,completed_at timestamptz,run_owner_id uuid NOT NULL,idempotency_key text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(program_id,tenant_id) REFERENCES evaluation_program(id,tenant_id),FOREIGN KEY(subject_id,tenant_id) REFERENCES evaluation_subject(id,tenant_id),FOREIGN KEY(dataset_id,tenant_id) REFERENCES evaluation_dataset(id,tenant_id));
CREATE TABLE evaluation_observation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,test_case_id uuid NOT NULL,metric_type text NOT NULL,value jsonb NOT NULL,evidence_ref text NOT NULL,captured_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id),FOREIGN KEY(test_case_id,tenant_id) REFERENCES evaluation_test_case(id,tenant_id));
CREATE TABLE human_evaluation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,test_case_id uuid NOT NULL,evaluator_id uuid NOT NULL,rubric jsonb NOT NULL,judgment text NOT NULL,rationale text NOT NULL,evaluated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,run_id,test_case_id,evaluator_id),FOREIGN KEY(run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id),FOREIGN KEY(test_case_id,tenant_id) REFERENCES evaluation_test_case(id,tenant_id));
CREATE TABLE quality_finding(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL,finding_type text NOT NULL,severity text NOT NULL,description text NOT NULL,evidence jsonb NOT NULL,status text NOT NULL DEFAULT 'open',reviewed_by uuid,reviewed_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id));
CREATE TABLE regression_comparison(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,baseline_run_id uuid NOT NULL,candidate_run_id uuid NOT NULL,deltas jsonb NOT NULL,findings jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',issued_by uuid,issued_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,baseline_run_id,candidate_run_id),FOREIGN KEY(baseline_run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id),FOREIGN KEY(candidate_run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id));
CREATE TABLE evaluation_waiver(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,finding_id uuid NOT NULL,scope jsonb NOT NULL,risk jsonb NOT NULL,controls jsonb NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'requested',requested_by uuid NOT NULL,decided_by uuid,decided_at timestamptz,rationale text,UNIQUE(id,tenant_id),FOREIGN KEY(finding_id,tenant_id) REFERENCES quality_finding(id,tenant_id));
CREATE TABLE release_advisory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,subject_id uuid NOT NULL,comparison_id uuid,recommendation text NOT NULL,rationale text NOT NULL,limitations jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',issued_by uuid,issued_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(subject_id,tenant_id) REFERENCES evaluation_subject(id,tenant_id),FOREIGN KEY(comparison_id,tenant_id) REFERENCES regression_comparison(id,tenant_id));
CREATE TABLE executive_quality_briefing(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,title text NOT NULL,version integer NOT NULL,content jsonb NOT NULL,citations jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',issued_by uuid,issued_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,title,version));
CREATE TABLE evaluation_advisory_request(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid,advisory_type text NOT NULL CHECK(advisory_type IN('nova','pops')),request_text text NOT NULL,response jsonb,status text NOT NULL DEFAULT 'requested',requested_by uuid NOT NULL,idempotency_key text NOT NULL,completed_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(run_id,tenant_id) REFERENCES evaluation_run(id,tenant_id));
CREATE TABLE evaluation_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(id,tenant_id));
CREATE INDEX idx_run_status ON evaluation_run(tenant_id,status); CREATE INDEX idx_finding_open ON quality_finding(tenant_id,status,severity); CREATE INDEX idx_subject_version ON evaluation_subject(tenant_id,subject_type,subject_id,subject_version); CREATE INDEX idx_eval_outbox ON evaluation_outbox(status,created_at) WHERE status='pending';
CREATE OR REPLACE FUNCTION prevent_evaluation_self_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE owner uuid; BEGIN IF TG_TABLE_NAME='evaluation_waiver' AND NEW.decided_by IS NOT NULL AND NEW.decided_by=NEW.requested_by THEN RAISE EXCEPTION 'self-approved waiver prohibited'; END IF; IF TG_TABLE_NAME='release_advisory' AND NEW.issued_by IS NOT NULL THEN SELECT run_owner_id INTO owner FROM evaluation_run r JOIN regression_comparison c ON c.candidate_run_id=r.id AND c.tenant_id=r.tenant_id WHERE c.id=NEW.comparison_id AND c.tenant_id=NEW.tenant_id; IF owner=NEW.issued_by THEN RAISE EXCEPTION 'run owner cannot issue own release advisory'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_waiver_self_approval BEFORE INSERT OR UPDATE ON evaluation_waiver FOR EACH ROW EXECUTE FUNCTION prevent_evaluation_self_approval(); CREATE TRIGGER trg_advisory_self_approval BEFORE INSERT OR UPDATE ON release_advisory FOR EACH ROW EXECUTE FUNCTION prevent_evaluation_self_approval();
CREATE OR REPLACE FUNCTION protect_evaluation_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_TABLE_NAME='evaluation_program' AND OLD.status='active') OR (TG_TABLE_NAME='evaluation_dataset' AND OLD.status='validated') OR (TG_TABLE_NAME='evaluation_scenario' AND OLD.status='approved') OR (TG_TABLE_NAME='evaluation_test_case' AND OLD.status='approved') OR TG_TABLE_NAME IN('evaluation_subject','evaluation_observation','human_evaluation') OR (TG_TABLE_NAME='evaluation_run' AND OLD.status='completed') OR (TG_TABLE_NAME='quality_finding' AND OLD.status='reviewed') OR (TG_TABLE_NAME='regression_comparison' AND OLD.status='issued') OR (TG_TABLE_NAME='evaluation_waiver' AND OLD.status IN('approved','rejected')) OR (TG_TABLE_NAME='release_advisory' AND OLD.status='issued') OR (TG_TABLE_NAME='executive_quality_briefing' AND OLD.status='issued') OR (TG_TABLE_NAME='evaluation_advisory_request' AND OLD.status='completed') THEN RAISE EXCEPTION 'evaluation record is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_program_immutable BEFORE UPDATE OR DELETE ON evaluation_program FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_dataset_immutable BEFORE UPDATE OR DELETE ON evaluation_dataset FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_scenario_immutable BEFORE UPDATE OR DELETE ON evaluation_scenario FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_case_immutable BEFORE UPDATE OR DELETE ON evaluation_test_case FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_subject_immutable BEFORE UPDATE OR DELETE ON evaluation_subject FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_run_immutable BEFORE UPDATE OR DELETE ON evaluation_run FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_observation_immutable BEFORE UPDATE OR DELETE ON evaluation_observation FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_human_eval_immutable BEFORE UPDATE OR DELETE ON human_evaluation FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_finding_immutable BEFORE UPDATE OR DELETE ON quality_finding FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_comparison_immutable BEFORE UPDATE OR DELETE ON regression_comparison FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_waiver_immutable BEFORE UPDATE OR DELETE ON evaluation_waiver FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_release_immutable BEFORE UPDATE OR DELETE ON release_advisory FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_quality_briefing_immutable BEFORE UPDATE OR DELETE ON executive_quality_briefing FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record(); CREATE TRIGGER trg_eval_advisory_immutable BEFORE UPDATE OR DELETE ON evaluation_advisory_request FOR EACH ROW EXECUTE FUNCTION protect_evaluation_record();
ALTER TABLE evaluation_program ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_dataset ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_scenario ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_test_case ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_subject ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_run ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_observation ENABLE ROW LEVEL SECURITY; ALTER TABLE human_evaluation ENABLE ROW LEVEL SECURITY; ALTER TABLE quality_finding ENABLE ROW LEVEL SECURITY; ALTER TABLE regression_comparison ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_waiver ENABLE ROW LEVEL SECURITY; ALTER TABLE release_advisory ENABLE ROW LEVEL SECURITY; ALTER TABLE executive_quality_briefing ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_advisory_request ENABLE ROW LEVEL SECURITY; ALTER TABLE evaluation_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY evaluation_program_tenant ON evaluation_program USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_dataset_tenant ON evaluation_dataset USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_scenario_tenant ON evaluation_scenario USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_case_tenant ON evaluation_test_case USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_subject_tenant ON evaluation_subject USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_run_tenant ON evaluation_run USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY observation_tenant ON evaluation_observation USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY human_evaluation_tenant ON human_evaluation USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY quality_finding_tenant ON quality_finding USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY comparison_tenant ON regression_comparison USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY waiver_tenant ON evaluation_waiver USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY release_advisory_tenant ON release_advisory USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY quality_briefing_tenant ON executive_quality_briefing USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_advisory_tenant ON evaluation_advisory_request USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evaluation_outbox_tenant ON evaluation_outbox USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid);
